function validate([coordinates, k]) {
  if (!Array.isArray(coordinates) || coordinates.length < 2 || coordinates.length > 50000) return 'coordinates needs 2 to 50000 points.';
  for (const point of coordinates) {
    if (!Array.isArray(point) || point.length !== 2) return 'Each point is a pair [x, y].';
    if (point.some(v => !Number.isInteger(v) || v < 0 || v > 1000000)) return 'Each coordinate is an integer from 0 to 10^6.';
  }
  if (!Number.isInteger(k) || k < 0 || k > 100) return 'k is an integer from 0 to 100.';
  return null;
}

