function countPairs(coordinates, k) {
  const seen = new Map();
  let count = 0;

  for (const [x, y] of coordinates) {
    for (let dx = 0; dx <= k; dx++) {
      const partnerX = x ^ dx;
      const partnerY = y ^ (k - dx);
      const partnerKey = partnerX * 2097152 + partnerY;
      count += seen.get(partnerKey) ?? 0;
    }
    const key = x * 2097152 + y;
    seen.set(key, (seen.get(key) ?? 0) + 1);
  }
  return count;
}

