function countPairs(coordinates, k) {
  let total = 0;
  for (let i = 0; i < coordinates.length; i++) {
    for (let j = i + 1; j < coordinates.length; j++) {
      const [a, b] = coordinates[i];
      const [c, d] = coordinates[j];
      if ((a ^ c) + (b ^ d) === k) total++;
    }
  }
  return total;
}

