function generate(rand, size) {
  const pick = (limit) => Math.floor(rand() * (limit + 1));
  if (size === 'large') {
    const n = 2000;
    const style = pick(2);
    // Narrow ranges make many pairs land at distance k; the wide range checks big coordinates.
    const span = style === 0 ? 63 : style === 1 ? 255 : 1000000;
    const base = style === 2 ? 0 : pick(1000000 - span);
    const k = style === 0 ? pick(100) : 50 + pick(50);
    const coordinates = Array.from({ length: n }, () => [base + pick(span), base + pick(span)]);
    return [coordinates, k];
  }
  const n = 2 + pick(8);
  const span = [1, 3, 7, 15][pick(3)];
  const shift = rand() < 0.2 ? 1000000 - span : 0;
  const coordinates = Array.from({ length: n }, () => [shift + pick(span), shift + pick(span)]);
  const k = rand() < 0.2 ? 0 : pick(2 * span + 2);
  return [coordinates, Math.min(k, 100)];
}
